result.output:
on: {'pull_request': {'types': ['labeled']}}
if: "github.event.label.name == 'to-review' && github.event.pull_request.draft == false"
steps: ['actions/checkout@v7', 'Install uv', 'Install dependencies', 'Run pr-reviewer', 'Mark as reviewed']
last step run: 'gh pr edit ${{ github.event.pull_request.number }} --repo ${{ github.repository }} --add-label reviewed'
perms: {'contents': 'read', 'pull-requests': 'write', 'id-token': 'write'}
